#!/usr/bin/env python3
"""Validate the Commitments Tracker CSVs against schema.md.

Usage:  python validate.py            (run from this directory)
Exit code 0 = clean, 1 = problems found. No dependencies beyond the stdlib.
"""
from __future__ import annotations

import csv
import re
import sys
from datetime import date
from pathlib import Path

HERE = Path(__file__).resolve().parent
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
URL_RE = re.compile(r"^https?://\S+$")

ENUMS = {
    "source_type": {"developer_doc", "government_commitment", "press", "other"},
    "category": {
        "evaluation", "deployment_gating", "disclosure", "incident_reporting",
        "security", "governance", "training_gating", "other",
    },
    "availability": {"general", "limited", "internal_only", "research_preview"},
    "third_party_testing_stated": {"yes", "no", "unclear"},
    "change_type": {"added", "removed", "weakened", "strengthened", "rescoped", "clarified"},
}

FILES = {
    "commitments.csv": {
        "columns": [
            "id", "developer", "document_title", "document_version", "published_on",
            "source_type", "source_url", "archive_url", "accessed_on", "category",
            "commitment_text", "quoted_passage", "conditions", "superseded_by",
            "notes", "entered_by", "checked_by",
        ],
        "required": ["id", "developer", "document_title", "published_on", "source_type",
                     "source_url", "accessed_on", "category", "commitment_text", "entered_by"],
        "dates": ["published_on", "accessed_on"],
        "urls": ["source_url", "archive_url"],
        "id_prefix": "C-",
    },
    "releases.csv": {
        "columns": [
            "id", "developer", "model_name", "announced_on", "availability",
            "announcement_url", "system_card_url", "system_card_published_on",
            "eval_results_url", "eval_results_published_on", "third_party_testing_stated",
            "third_party_testing_url", "applicable_commitment_ids", "rechecked_on",
            "accessed_on", "notes", "entered_by", "checked_by",
        ],
        "required": ["id", "developer", "model_name", "announced_on", "availability",
                     "announcement_url", "accessed_on", "entered_by"],
        "dates": ["announced_on", "system_card_published_on", "eval_results_published_on",
                  "rechecked_on", "accessed_on"],
        "urls": ["announcement_url", "system_card_url", "eval_results_url",
                 "third_party_testing_url"],
        "id_prefix": "R-",
    },
    "changes.csv": {
        "columns": [
            "id", "developer", "from_commitment_id", "to_commitment_id", "change_type",
            "before_text", "after_text", "observed_on", "developer_explanation_url",
            "notes", "entered_by", "checked_by",
        ],
        "required": ["id", "developer", "from_commitment_id", "change_type", "before_text",
                     "observed_on", "entered_by"],
        "dates": ["observed_on"],
        "urls": ["developer_explanation_url"],
        "id_prefix": "CH-",
    },
}

# Words that signal a verdict rather than a fact. Flagged as warnings, not errors.
LOADED = re.compile(
    r"\b(fail(ed|s|ure)?|broke|broken|promis(ed|es)?\s+but|quietly|merely|only|"
    r"refus(ed|es)|ignor(ed|es)|misleading|dishonest|reckless|irresponsible)\b",
    re.IGNORECASE,
)


def load(path: Path) -> list[dict]:
    with path.open(newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def main() -> int:
    errors: list[str] = []
    warnings: list[str] = []
    today = date.today().isoformat()

    developers = {r["developer"] for r in load(HERE / "developers.csv")} if (HERE / "developers.csv").exists() else set()
    commitment_ids: set[str] = set()

    for fname, spec in FILES.items():
        path = HERE / fname
        if not path.exists():
            errors.append(f"{fname}: missing")
            continue
        with path.open(newline="", encoding="utf-8") as f:
            header = next(csv.reader(f), [])
        if header != spec["columns"]:
            errors.append(f"{fname}: header does not match schema.md\n   expected {spec['columns']}\n   got      {header}")
            continue

        rows = load(path)
        seen_ids: set[str] = set()
        for n, row in enumerate(rows, start=2):
            where = f"{fname}:{n}"
            rid = row.get("id", "")
            if not rid.startswith(spec["id_prefix"]):
                errors.append(f"{where}: id '{rid}' must start with {spec['id_prefix']}")
            if rid in seen_ids:
                errors.append(f"{where}: duplicate id {rid}")
            seen_ids.add(rid)
            for col in spec["required"]:
                if not row.get(col, "").strip():
                    errors.append(f"{where}: required column '{col}' is empty")
            for col in spec["dates"]:
                v = row.get(col, "")
                if v and not DATE_RE.match(v):
                    errors.append(f"{where}: '{col}' must be YYYY-MM-DD, got '{v}'")
                if v and v > today:
                    errors.append(f"{where}: '{col}' is in the future ({v})")
            for col in spec["urls"]:
                v = row.get(col, "")
                if v and not URL_RE.match(v):
                    errors.append(f"{where}: '{col}' is not a URL: '{v}'")
            for col, allowed in ENUMS.items():
                if col in row and row[col] and row[col] not in allowed:
                    errors.append(f"{where}: '{col}'='{row[col]}' not in {sorted(allowed)}")
            if developers and row.get("developer") and row["developer"] not in developers:
                errors.append(f"{where}: developer '{row['developer']}' not in developers.csv")
            for col in ("commitment_text", "notes", "before_text", "after_text"):
                v = row.get(col, "")
                if v and LOADED.search(v):
                    warnings.append(f"{where}: '{col}' contains a loaded word — rephrase neutrally: {v[:80]!r}")
            if not row.get("archive_url") and fname == "commitments.csv":
                warnings.append(f"{where}: no archive_url (strongly preferred)")

        if fname == "commitments.csv":
            commitment_ids = seen_ids

        if fname == "releases.csv":
            for n, row in enumerate(rows, start=2):
                where = f"{fname}:{n}"
                missing_artefact = not row.get("system_card_url") or not row.get("eval_results_url")
                if missing_artefact and not row.get("rechecked_on"):
                    errors.append(f"{where}: artefact URL empty but 'rechecked_on' not set (rule 4)")
                for cid in filter(None, row.get("applicable_commitment_ids", "").split(";")):
                    if cid.strip() not in commitment_ids:
                        errors.append(f"{where}: applicable_commitment_id '{cid}' not found")

        if fname == "changes.csv":
            for n, row in enumerate(rows, start=2):
                where = f"{fname}:{n}"
                for col in ("from_commitment_id", "to_commitment_id"):
                    v = row.get(col, "")
                    if v and v not in commitment_ids:
                        errors.append(f"{where}: '{col}'='{v}' not found in commitments.csv")
                if row.get("change_type") == "removed" and row.get("to_commitment_id"):
                    errors.append(f"{where}: change_type 'removed' must have empty to_commitment_id")

    for w in warnings:
        print("WARN ", w)
    for e in errors:
        print("ERROR", e)
    print(f"\n{len(errors)} error(s), {len(warnings)} warning(s)")
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())
